const wait=ms=>new Promise(r=>setTimeout(r,ms)), raf=()=>new Promise(r=>requestAnimationFrame(()=>r()));
const key=(t,k,c)=>window.dispatchEvent(new KeyboardEvent(t,{key:k,code:c,bubbles:true}));
let t=performance.now(), x=0; for(let i=0;i<2e7;i++) x+=i%7; const cpu=performance.now()-t;
const fr=[]; let last=performance.now(); for(let i=0;i<30;i++){ await raf(); const n=performance.now(); fr.push(n-last); last=n; } fr.sort((a,b)=>a-b);
const tm=[]; for(let i=0;i<10;i++){ const a=performance.now(); await wait(20); tm.push(performance.now()-a); } tm.sort((a,b)=>a-b);
const lg=[]; for(let i=0;i<5;i++){ const a=performance.now(); key('keydown',' ','Space'); const s=performance.now()-a; await raf(); const r1=performance.now()-a; await raf(); const r2=performance.now()-a; key('keyup',' ','Space'); await wait(300); key('keydown','Escape','Escape'); key('keyup','Escape','Escape'); await wait(300); lg.push(s.toFixed(0)+'/'+r1.toFixed(0)+'/'+r2.toFixed(0)); }
const f=v=>v.toFixed(1);
return 'diag · cpu 2e7 loop '+f(cpu)+' ms · rAF gap p50 '+f(fr[15])+' max '+f(fr[29])+' ms · setTimeout(20) p50 '+f(tm[5])+' max '+f(tm[9])+' ms · large open sync/rAF1/rAF2 '+lg.join(' ')+' ms · '+document.visibilityState+' · dpr '+devicePixelRatio+' · cores '+navigator.hardwareConcurrency;
